export function getGrade12Subject(trackSlug: string, subjectSlug: string, edition: Grade12Edition): Grade12Subject | undefined {
  const candidates = grade12Subjects.filter((subject) =>
    subject.slug === subjectSlug && (subject.track === "both" || subject.track === trackSlug),
  );
  return candidates.find((subject) => subject.edition === edition)
    ?? candidates.find((subject) => subject.edition === "common-2026");
}

export function getGrade12SourceState(status: Grade12Subject["sourceStatus"]): string {
  if (status === "toc-verified") return "فهرس موثق من سجل الكتاب";
  if (status === "toc-partial") return "فهرس جزئي — يحتاج استكمال";
  return "فهرس الكتاب قيد المراجعة";
}
